	tranTime := time.Now().Sub(transactionStartTime).Milliseconds()

	c.Metrics().RecordHistogram(c, transactionTime, float64(tranTime))
	c.Metrics().DeltaUpDownCounter(c, totalCreditDaySales, 1000, "sale_type", "credit")
