func TestIntegration(t *testing.T) {
	configs := testutil.NewServerConfigs(t)

	go main()
	time.Sleep(100 * time.Millisecond) // Giving some time to start the server

	c := http.Client{}

	req, _ := http.NewRequest(http.MethodPost, configs.HTTPHost+"/transaction", nil)
	req.Header.Set("content-type", "application/json")

	_, err := c.Do(req)
	if err != nil {
		t.Fatalf("request to /transaction failed %v", err)
	}

	req, _ = http.NewRequest(http.MethodPost, configs.HTTPHost+"/return", nil)

	_, err = c.Do(req)
	if err != nil {
		t.Fatalf("request to /transaction failed %v", err)
	}

	req, _ = http.NewRequest(http.MethodGet, fmt.Sprintf("http://localhost:%d/metrics", configs.MetricsPort), nil)

	resp, err := c.Do(req)
	if err != nil {
		t.Fatalf("request to localhost:%d/metrics failed: %v", configs.MetricsPort, err)
	}

	body, _ := io.ReadAll(resp.Body)

	strBody := string(body)

	assert.Equal(t, http.StatusOK, resp.StatusCode, "TEST[%d], Failed.\n%s")

	assert.Contains(t, strBody, `product_stock{otel_scope_name="using-metrics",otel_scope_version="v0.1.0"} 50`)
	assert.Contains(t, strBody, `total_credit_day_sale{otel_scope_name="using-metrics",otel_scope_version="v0.1.0",sale_type="credit"} 1000`)
	assert.Contains(t, strBody, `total_credit_day_sale{otel_scope_name="using-metrics",otel_scope_version="v0.1.0",sale_type="credit_return"} -1000`)
	assert.Contains(t, strBody, `transaction_success_total{otel_scope_name="using-metrics",otel_scope_version="v0.1.0"} 1`)
	assert.Contains(t, strBody, "transaction_time")
}

func UploadHandler(c *gofr.Context) (interface{}, error) {
	var d Data

	// bind the multipart data into the variable d
	err := c.Bind(&d)
	if err != nil {
		return nil, err
	}

	// create local copies of the zipped files in tmp folder
	err = d.Compressed.CreateLocalCopies("tmp")
	if err != nil {
		return nil, err
	}

	defer os.RemoveAll("tmp")

	f, err := d.FileHeader.Open()
	if err != nil {
		return nil, err
	}

	defer f.Close()

	// read the file content
	content, err := io.ReadAll(f)
	if err != nil {
		return false, err
	}

	// return the number of compressed files received
	return fmt.Sprintf("zipped files: %d, len of file `a`: %d", len(d.Compressed.Files), len(content)), nil
}

