func spinner(ctx *gofr.Context) (interface{}, error) {
	// initialize the spinner
	sp := terminal.NewDotSpinner(ctx.Out)
	sp.Spin(ctx)

	defer sp.Stop()

	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-time.After(2 * time.Second):
	}

	return "Process Complete", nil
}

