func WSHandler(ctx *gofr.Context) (interface{}, error) {
	var message string

	err := ctx.Bind(&message)
	if err != nil {
		ctx.Logger.Errorf("Error binding message: %v", err)
		return nil, err
	}

	ctx.Logger.Infof("Received message: %s", message)

	err = ctx.WriteMessageToSocket("Hello! GoFr")
	if err != nil {
		return nil, err
	}

	return message, nil
}

func (r *Request) Bind(i interface{}) error {
	// pointer to struct - addressable
	ps := reflect.ValueOf(i)
	// struct
	s := ps.Elem()

	if s.Kind() != reflect.Struct {
		return nil
	}

	for k, v := range r.params {
		f := s.FieldByName(k)
		// A Value can be changed only if it is addressable and not unexported struct field
		if !f.IsValid() || !f.CanSet() {
			continue
		}
		//nolint:exhaustive // no need to add other cases
		switch f.Kind() {
		case reflect.String:
			f.SetString(v)
		case reflect.Bool:
			if v == trueString {
				f.SetBool(true)
			}
		case reflect.Int:
			n, _ := strconv.Atoi(v)
