func TestMessage_Bind(t *testing.T) {
	testCases := []struct {
		desc     string
		input    interface{}
		value    []byte
		expected interface{}
		hasError bool
	}{
		{
			desc:     "bind to string",
			input:    new(string),
			value:    []byte("test"),
			expected: "test",
			hasError: false,
		},
		{
			desc:     "bind to float64",
			input:    new(float64),
			value:    []byte("1.23"),
			expected: 1.23,
			hasError: false,
		},
		{
			desc:     "bind to int",
			input:    new(int),
			value:    []byte("123"),
			expected: 123,
			hasError: false,
		},
		{
			desc:     "bind to bool",
			input:    new(bool),
			value:    []byte("true"),
			expected: true,
			hasError: false,
		},
		{
			desc:     "bind to map[string]interface{}",
			input:    &map[string]interface{}{},
			value:    []byte(`{"key":"value"}`),
			expected: &map[string]interface{}{"key": "value"},
			hasError: false,
		},
		{
			desc:     "bind to struct",
			input:    &struct{ Name string }{},
			value:    []byte(`{"Name":"test"}`),
			expected: &struct{ Name string }{Name: "test"},
			hasError: false,
		},
		{
			desc:     "bind to not pointer",
			input:    struct{ Name string }{},
			value:    []byte(`{"Name":"test"}`),
			expected: &struct{ Name string }{},
			hasError: true,
		},
		{
			desc:     "bind to struct with error",
			input:    &struct{ Name string }{},
			value:    []byte(`{"Name":}`),
			expected: &struct{ Name string }{},
			hasError: true,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.desc, func(t *testing.T) {
			m := NewMessage(context.Background())
			m.Value = tc.value

			err := m.Bind(tc.input)

			if tc.hasError {
				require.Error(t, err)
			} else {
				require.NoError(t, err)

				switch v := tc.input.(type) {
				case *string:
					assert.Equal(t, tc.expected, *v)
				case *float64:
					assert.InEpsilon(t, tc.expected, *v, 0.01)
				case *int:
					assert.Equal(t, tc.expected, *v)
				case *bool:
					assert.Equal(t, tc.expected, *v)
				default:
					assert.Equal(t, tc.expected, v)
				}
			}
		})
	}
}

