func (ql *QueryLog) String() string {
	if ql.Args == nil {
		return ""
	}

	switch args := ql.Args.(type) {
	case []interface{}:
		strArgs := make([]string, len(args))
		for i, arg := range args {
			strArgs[i] = fmt.Sprint(arg)
		}

		return strings.Join(strArgs, " ")
	default:
		return fmt.Sprint(ql.Args)
	}
}

