func Test_Insert(t *testing.T) {
	ctrl := gomock.NewController(t)
	defer ctrl.Finish()

	mockLogger := NewMockLogger(ctrl)
	mockConn := NewMockConnection(ctrl)
	mockMetrics := NewMockMetrics(ctrl)

	client := New(&Config{
		Namespace: "test_ns",
		Database:  "test_db",
	})
	client.UseLogger(mockLogger)
	client.UseMetrics(mockMetrics)
	client.db = mockConn

	t.Run("successful insert", func(t *testing.T) {
		ctx := context.Background()
		data := map[string]any{
			"name":  "test",
			"email": "test@example.com",
		}

		mockResponse := DBResponse{
			Result: []any{
				map[string]any{
					"id":    "user:1",
					"name":  "test",
					"email": "test@example.com",
				},
			},
		}

		mockLogger.EXPECT().Debug(gomock.Any()).AnyTimes()
		mockConn.EXPECT().
			Send(gomock.Any(), "insert", "users", data).
			Return(nil).
			SetArg(0, mockResponse)

		result, err := client.Insert(ctx, "users", data)
		require.NoError(t, err)
		require.Len(t, result, 1)
		assert.Equal(t, "test", result[0]["name"])
		assert.Equal(t, "test@example.com", result[0]["email"])
	})

	t.Run("not connected error", func(t *testing.T) {
		ctx := context.Background()
		client.db = nil

		mockLogger.EXPECT().Debug(gomock.Any()).AnyTimes()

		result, err := client.Insert(ctx, "users", nil)
		require.ErrorIs(t, err, errNotConnected)
		require.Nil(t, result)

		client.db = mockConn
	})

	t.Run("unexpected result type error", func(t *testing.T) {
		ctx := context.Background()
		data := map[string]any{"name": "test"}

		mockResponse := DBResponse{
			Result: "invalid result type",
		}

		mockLogger.EXPECT().Debug(gomock.Any()).AnyTimes()
		mockConn.EXPECT().
			Send(gomock.Any(), "insert", "users", data).
			Return(nil).
			SetArg(0, mockResponse)

		result, err := client.Insert(ctx, "users", data)
		require.ErrorIs(t, err, errUnexpectedResultType)
		require.Nil(t, result)
	})
}

func (a *App) RegisterService(desc *grpc.ServiceDesc, impl any) {
	if !a.grpcRegistered && !isPortAvailable(a.grpcServer.port) {
		a.container.Logger.Fatalf("gRPC port %d is blocked or unreachable", a.grpcServer.port)
	}

	a.container.Logger.Infof("registering gRPC Server: %s", desc.ServiceName)
	a.grpcServer.server.RegisterService(desc, impl)

	err := injectContainer(impl, a.container)
	if err != nil {
		return
	}

	a.grpcRegistered = true
}

