func (c *Checker) signatureToStringEx(signature *Signature, enclosingDeclaration *ast.Node, flags TypeFormatFlags) string {
	isConstructor := signature.flags&SignatureFlagsConstruct != 0
	var sigOutput ast.Kind
	if flags&TypeFormatFlagsWriteArrowStyleSignature != 0 {
		if isConstructor {
			sigOutput = ast.KindConstructorType
		} else {
			sigOutput = ast.KindFunctionType
		}
	} else {
		if isConstructor {
			sigOutput = ast.KindConstructSignature
		} else {
			sigOutput = ast.KindCallSignature
		}
	}
	writer, putWriter := printer.GetSingleLineStringWriter()
	defer putWriter()

	combinedFlags := toNodeBuilderFlags(flags) | nodebuilder.FlagsIgnoreErrors | nodebuilder.FlagsWriteTypeParametersInQualifiedName
	sig := c.nodeBuilder.SignatureToSignatureDeclaration(signature, sigOutput, enclosingDeclaration, combinedFlags, nodebuilder.InternalFlagsNone, nil)
	printer_ := createPrinterWithRemoveCommentsOmitTrailingSemicolon(c.diagnosticConstructionContext)
	var sourceFile *ast.SourceFile
	if enclosingDeclaration != nil {
		sourceFile = ast.GetSourceFileOfNode(enclosingDeclaration)
	}
	printer_.Write(sig /*sourceFile*/, sourceFile, getTrailingSemicolonDeferringWriter(writer), nil) // TODO: GH#18217
	return writer.String()
}

func (r *Relater) hasExcessProperties(source *Type, target *Type, reportErrors bool) bool {
	if !isExcessPropertyCheckTarget(target) || !r.c.noImplicitAny && target.objectFlags&ObjectFlagsJSLiteral != 0 {
		// Disable excess property checks on JS literals to simulate having an implicit "index signature" - but only outside of noImplicitAny
		return false
	}
	isComparingJsxAttributes := source.objectFlags&ObjectFlagsJsxAttributes != 0
	if (r.relation == r.c.assignableRelation || r.relation == r.c.comparableRelation) && (r.c.isTypeSubsetOf(r.c.globalObjectType, target) || (!isComparingJsxAttributes && r.c.isEmptyObjectType(target))) {
		return false
	}
	reducedTarget := target
	var checkTypes []*Type
	// ... (7 lines folded)
	for _, prop := range r.c.getPropertiesOfType(source) {
		if shouldCheckAsExcessProperty(prop, source.symbol) && !isIgnoredJsxProperty(source, prop) {
			if !r.c.isKnownProperty(reducedTarget, prop.Name, isComparingJsxAttributes) {
				if reportErrors {
					// Report error in terms of object types in the target as those are the only ones
					// we check in isKnownProperty.
					errorTarget := r.c.filterType(reducedTarget, isExcessPropertyCheckTarget)
					// We know *exactly* where things went wrong when comparing the types.
					// Use this property as the error node as this will be more helpful in
					// reasoning about what went wrong.
					if r.errorNode == nil {
						panic("No errorNode in hasExcessProperties")
					}
					if ast.IsJsxAttributes(r.errorNode) || isJsxOpeningLikeElement(r.errorNode) || isJsxOpeningLikeElement(r.errorNode.Parent) {
						// JsxAttributes has an object-literal flag and undergo same type-assignablity check as normal object-literal.
						// However, using an object-literal error message will be very confusing to the users so we give different a message.
						// ... (34 lines folded)
				}
				return true
			}
			// ... (6 lines folded)
		}
	}
	return false
}

func runWithoutResolvedSignatureCaching[T any](c *Checker, node *ast.Node, fn func() T) T {
	ancestorNode := ast.FindAncestor(node, func(n *ast.Node) bool {
		return ast.IsCallLikeOrFunctionLikeExpression(n)
	})
	if ancestorNode != nil {
		cachedResolvedSignatures := make(map[*SignatureLinks]*Signature)
		cachedTypes := make(map[*ValueSymbolLinks]*Type)
		for ancestorNode != nil {
			signatureLinks := c.signatureLinks.Get(ancestorNode)
			cachedResolvedSignatures[signatureLinks] = signatureLinks.resolvedSignature
			signatureLinks.resolvedSignature = nil
			if ast.IsFunctionExpressionOrArrowFunction(ancestorNode) {
				symbolLinks := c.valueSymbolLinks.Get(c.getSymbolOfDeclaration(ancestorNode))
				resolvedType := symbolLinks.resolvedType
				cachedTypes[symbolLinks] = resolvedType
				symbolLinks.resolvedType = nil
			}
			ancestorNode = ast.FindAncestor(ancestorNode.Parent, ast.IsCallLikeOrFunctionLikeExpression)
		}
		result := fn()
		for signatureLinks, resolvedSignature := range cachedResolvedSignatures {
			signatureLinks.resolvedSignature = resolvedSignature
		}
		for symbolLinks, resolvedType := range cachedTypes {
			symbolLinks.resolvedType = resolvedType
		}
		return result
	}
	return fn()
}

func (b *nodeBuilderImpl) getSpecifierForModuleSymbol(symbol *ast.Symbol, overrideImportMode core.ResolutionMode) string {
	file := ast.GetDeclarationOfKind(symbol, ast.KindSourceFile)
	if file == nil {
		equivalentSymbol := core.FirstNonNil(symbol.Declarations, func(d *ast.Node) *ast.Symbol {
			return b.ch.getFileSymbolIfFileSymbolExportEqualsContainer(d, symbol)
		})
		if equivalentSymbol != nil {
			file = ast.GetDeclarationOfKind(equivalentSymbol, ast.KindSourceFile)
		}
	}

	if file == nil {
		if isAmbientModuleSymbolName(symbol.Name) {
			return stringutil.StripQuotes(symbol.Name)
		}
	}
	if b.ctx.enclosingFile == nil || b.ctx.tracker.GetModuleSpecifierGenerationHost() == nil {
		if isAmbientModuleSymbolName(symbol.Name) {
			return stringutil.StripQuotes(symbol.Name)
		}
		return ast.GetSourceFileOfModule(symbol).FileName()
	}

	enclosingDeclaration := b.e.MostOriginal(b.ctx.enclosingDeclaration)
	var originalModuleSpecifier *ast.Node
	if canHaveModuleSpecifier(enclosingDeclaration) {
		originalModuleSpecifier = tryGetModuleSpecifierFromDeclaration(enclosingDeclaration)
	}
	contextFile := b.ctx.enclosingFile
	resolutionMode := overrideImportMode
	if resolutionMode == core.ResolutionModeNone && originalModuleSpecifier != nil {
		// !!! import resolution mode support
		// resolutionMode = b.ch.host.GetModeForUsageLocation(contextFile, originalModuleSpecifier)
	} else if resolutionMode == core.ResolutionModeNone && contextFile != nil {
		// !!! import resolution mode support
		// resolutionMode = b.ch.host.GetDefaultResolutionModeForFile(contextFile)
	}
	cacheKey := module.ModeAwareCacheKey{Name: string(contextFile.Path()), Mode: resolutionMode}
	links := b.symbolLinks.Get(symbol)
	if links.specifierCache == nil {
		links.specifierCache = make(module.ModeAwareCache[string])
	}
	result, ok := links.specifierCache[cacheKey]
	if ok {
		return result
	}
	isBundle := len(b.ch.compilerOptions.OutFile) > 0
	// For declaration bundles, we need to generate absolute paths relative to the common source dir for imports,
	// just like how the declaration emitter does for the ambient module declarations - we can easily accomplish this
	// using the `baseUrl` compiler option (which we would otherwise never use in declaration emit) and a non-relative
	// specifier preference
	host := b.ctx.tracker.GetModuleSpecifierGenerationHost()
	specifierCompilerOptions := b.ch.compilerOptions
	specifierPref := modulespecifiers.ImportModuleSpecifierPreferenceProjectRelative
	endingPref := modulespecifiers.ImportModuleSpecifierEndingPreferenceNone
	if resolutionMode == core.ResolutionModeESM {
		endingPref = modulespecifiers.ImportModuleSpecifierEndingPreferenceJs
	}
	if isBundle {
		// !!! relies on option cloning and specifier host implementation
		// specifierCompilerOptions = &core.CompilerOptions{BaseUrl: host.GetCommonSourceDirectory()}
		// TODO: merge with b.ch.compilerOptions
		specifierPref = modulespecifiers.ImportModuleSpecifierPreferenceNonRelative
		endingPref = modulespecifiers.ImportModuleSpecifierEndingPreferenceMinimal
	}

	allSpecifiers := modulespecifiers.GetModuleSpecifiers(
		symbol,
		b.ch,
		specifierCompilerOptions,
		contextFile,
		host,
		modulespecifiers.UserPreferences{
			ImportModuleSpecifierPreference:       specifierPref,
			ImportModuleSpecifierEndingPreference: endingPref,
		},
		modulespecifiers.ModuleSpecifierOptions{
			OverrideImportMode: overrideImportMode,
		},
	)
	specifier := allSpecifiers[0]
	links.specifierCache[cacheKey] = specifier
	return specifier
}

func (c *Checker) GetConstantValue(node *ast.Node) any {
	if node.Kind == ast.KindEnumMember {
		return c.getEnumMemberValue(node).Value
	}

	if c.symbolNodeLinks.Get(node).resolvedSymbol == nil {
		c.checkExpressionCached(node) // ensure cached resolved symbol is set
	}
	symbol := c.symbolNodeLinks.Get(node).resolvedSymbol
	if symbol == nil && ast.IsEntityNameExpression(node) {
		symbol = c.resolveEntityName(
			node,
			ast.SymbolFlagsValue,
			true,  /*ignoreErrors*/
			false, /*dontResolveAlias*/
			nil /*location*/)
	}
	if symbol != nil && symbol.Flags&ast.SymbolFlagsEnumMember != 0 {
		// inline property\index accesses only for const enums
		member := symbol.ValueDeclaration
		if ast.IsEnumConst(member.Parent) {
			return c.getEnumMemberValue(member).Value
		}
	}

	return nil
}

