		default:
			// Debug.assertNever(preferredEnding); // !!!
		}
		return []ModuleSpecifierEnding{ModuleSpecifierEndingMinimal}
	}

	return ModuleSpecifierPreferences{
		excludeRegexes:                    excludes,
