func comparePathsByRedirectAndNumberOfDirectorySeparators(a ModulePath, b ModulePath) int {
	if a.IsRedirect == b.IsRedirect {
		return strings.Count(a.Path, "/") - strings.Count(b.Path, "/")
	}
	if a.IsRedirect {
		return 1
	}
	return -1
}

