func (l *LanguageService) GetDocumentDiagnostics(ctx context.Context, documentURI lsproto.DocumentUri) (*lsproto.DocumentDiagnosticReport, error) {
	program, file := l.getProgramAndFile(documentURI)

	diagnostics := make([][]*ast.Diagnostic, 0, 3)
	if syntaxDiagnostics := program.GetSyntacticDiagnostics(ctx, file); len(syntaxDiagnostics) != 0 {
		diagnostics = append(diagnostics, syntaxDiagnostics)
	} else {
		diagnostics = append(diagnostics, program.GetSemanticDiagnostics(ctx, file))
		// !!! user preference for suggestion diagnostics; keep only unnecessary/deprecated?
		// See: https://github.com/microsoft/vscode/blob/3dbc74129aaae102e5cb485b958fa5360e8d3e7a/extensions/typescript-language-features/src/languageFeatures/diagnostics.ts#L114
		diagnostics = append(diagnostics, program.GetSuggestionDiagnostics(ctx, file))
		if program.Options().GetEmitDeclarations() {
			diagnostics = append(diagnostics, program.GetDeclarationDiagnostics(ctx, file))
		}
	}

	return &lsproto.DocumentDiagnosticReport{
		RelatedFullDocumentDiagnosticReport: &lsproto.RelatedFullDocumentDiagnosticReport{
			FullDocumentDiagnosticReport: lsproto.FullDocumentDiagnosticReport{
				Items: toLSPDiagnostics(l.converters, diagnostics...),
			},
		},
	}, nil
}

func (l *LanguageService) getReferencedSymbolsForNode(position int, node *ast.Node, program *compiler.Program, sourceFiles []*ast.SourceFile, options refOptions, sourceFilesSet *collections.Set[string]) []*SymbolAndEntries {
	// !!! cancellationToken
	// ... (6 lines folded)

	if node.Kind == ast.KindSourceFile {
		resolvedRef := getReferenceAtPosition(node.AsSourceFile(), position, program)
		if resolvedRef.file == nil {
			return nil
		}

		checker, done := program.GetTypeChecker(l.ctx)
		defer done()

		if moduleSymbol := checker.GetMergedSymbol(resolvedRef.file.Symbol); moduleSymbol != nil {
			return getReferencedSymbolsForModule(program, moduleSymbol /*excludeImportTypeOfExportEquals*/, false, sourceFiles, sourceFilesSet)
		}

		// !!! not implemented
		// fileIncludeReasons := program.getFileIncludeReasons();
		// if (!fileIncludeReasons) {
		// 	return nil
		// }
		return []*SymbolAndEntries{{
			definition: &Definition{Kind: definitionKindTripleSlashReference, tripleSlashFileRef: &tripleSlashDefinition{reference: resolvedRef.reference}},
			references: getReferencesForNonModule(resolvedRef.file, program /*fileIncludeReasons,*/),
		}}
	}

	// ... (6 lines folded)

	checker, done := program.GetTypeChecker(l.ctx)
	defer done()

	// constructors should use the class symbol, detected by name, if present
	symbol := checker.GetSymbolAtLocation(core.IfElse(node.Kind == ast.KindConstructor && node.Parent.Name() != nil, node.Parent.Name(), node))
	// Could not find a symbol e.g. unknown identifier
	// ... (22 lines folded)

	if symbol.Name == ast.InternalSymbolNameExportEquals {
		return getReferencedSymbolsForModule(program, symbol.Parent, false /*excludeImportTypeOfExportEquals*/, sourceFiles, sourceFilesSet)
	}

	moduleReferences := l.getReferencedSymbolsForModuleIfDeclaredBySourceFile(symbol, program, sourceFiles, options, sourceFilesSet) // !!! cancellationToken
	if moduleReferences != nil && symbol.Flags&ast.SymbolFlagsTransient != 0 {
		return moduleReferences
	}

	aliasedSymbol := getMergedAliasedSymbolOfNamespaceExportDeclaration(node, symbol, checker)
	moduleReferencesOfExportTarget := l.getReferencedSymbolsForModuleIfDeclaredBySourceFile(aliasedSymbol, program, sourceFiles, options, sourceFilesSet) // !!! cancellationToken

	references := getReferencedSymbolsForSymbol(symbol, node, sourceFiles, sourceFilesSet, checker, options) // !!! cancellationToken
	return l.mergeReferences(program, moduleReferences, references, moduleReferencesOfExportTarget)
}

func runFindReferencesTest(t *testing.T, input string, expectedLocations map[string]*collections.Set[string]) {
	testData := fourslash.ParseTestData(t, input, "/file1.ts")
	markerPositions := testData.MarkerPositions
	ctx := projecttestutil.WithRequestID(t.Context())
	service, done := createLanguageService(ctx, testData.Files[0].FileName(), map[string]string{
		testData.Files[0].FileName(): testData.Files[0].Content,
	})
	defer done()

	// for each marker location, calculate the expected ref location ahead of time so we don't have to re-calculate each location for every reference call
	allExpectedLocations := map[lsproto.Location]string{}
	for _, expectedRange := range testData.Ranges {
		allExpectedLocations[*service.GetExpectedReferenceFromMarker(expectedRange.FileName(), expectedRange.Position)] = *expectedRange.Name
	}

	for requestMarkerName, expectedSet := range expectedLocations {
		marker, ok := markerPositions[requestMarkerName]
		if !ok {
			t.Fatalf("No marker found for '%s'", requestMarkerName)
		}

		referencesResult := service.TestProvideReferences(marker.FileName(), marker.Position)
		libReference := 0

		for _, loc := range referencesResult {
			if name, ok := allExpectedLocations[*loc]; ok {
				// check if returned ref location is in this request's expected set
				assert.Assert(t, expectedSet.Has(name), "Reference to '%s' not expected when find all references requested at %s", name, requestMarkerName)
			} else if strings.Contains(string(loc.Uri), "//bundled") && strings.Contains(string(loc.Uri), "//libs") {
				libReference += 1
			} else {
				t.Fatalf("Found reference at loc '%v' when find all references triggered at '%s'", loc, requestMarkerName)
			}
		}
		expectedNum := expectedSet.Len() + libReference
		assert.Assert(t, len(referencesResult) == expectedNum, "assertion failed: expected %d references at marker %s, got %d", expectedNum, requestMarkerName, len(referencesResult))
	}
}

func (l *LanguageService) ProvideTypeDefinition(ctx context.Context, documentURI lsproto.DocumentUri, position lsproto.Position) (*lsproto.Definition, error) {
	program, file := l.getProgramAndFile(documentURI)
	node := astnav.GetTouchingPropertyName(file, int(l.converters.LineAndCharacterToPosition(file, position)))
	if node.Kind == ast.KindSourceFile {
		return nil, nil
	}

	c, done := program.GetTypeCheckerForFile(ctx, file)
	defer done()

	node = getDeclarationNameForKeyword(node)

	if symbol := c.GetSymbolAtLocation(node); symbol != nil {
		symbolType := getTypeOfSymbolAtLocation(c, symbol, node)
		declarations := getDeclarationsFromType(symbolType)
		if typeArgument := c.GetFirstTypeArgumentFromKnownType(symbolType); typeArgument != nil {
			declarations = core.Concatenate(getDeclarationsFromType(typeArgument), declarations)
		}
		if len(declarations) != 0 {
			return l.createLocationsFromDeclarations(declarations), nil
		}
		if symbol.Flags&ast.SymbolFlagsValue == 0 && symbol.Flags&ast.SymbolFlagsType != 0 {
			return l.createLocationsFromDeclarations(symbol.Declarations), nil
		}
	}

	return nil, nil
}

