func (p *Parser) reparseJSDocSignature(jsSignature *ast.Node, fun *ast.Node, jsDoc *ast.Node, tag *ast.Node, modifiers *ast.ModifierList) *ast.Node {
	var signature *ast.Node
	clonedModifiers := p.factory.DeepCloneReparseModifiers(modifiers)
	switch fun.Kind {
	case ast.KindFunctionDeclaration, ast.KindFunctionExpression, ast.KindArrowFunction:
		signature = p.factory.NewFunctionDeclaration(clonedModifiers, nil, p.factory.DeepCloneReparse(fun.Name()), nil, nil, nil, nil)
	case ast.KindMethodDeclaration, ast.KindMethodSignature:
		signature = p.factory.NewMethodDeclaration(clonedModifiers, nil, p.factory.DeepCloneReparse(fun.Name()), nil, nil, nil, nil, nil)
	case ast.KindConstructor:
		signature = p.factory.NewConstructorDeclaration(clonedModifiers, nil, nil, nil, nil)
	case ast.KindJSDocCallbackTag:
		signature = p.factory.NewFunctionTypeNode(nil, nil, nil)
	default:
		panic("Unexpected kind " + fun.Kind.String())
	}

	if tag.Kind != ast.KindJSDocCallbackTag {
		signature.FunctionLikeData().TypeParameters = p.gatherTypeParameters(jsDoc, tag)
	}
	parameters := p.nodeSlicePool.NewSlice(0)
	for _, param := range jsSignature.Parameters() {
		var parameter *ast.Node
		if param.Kind == ast.KindJSDocThisTag {
			thisTag := param.AsJSDocThisTag()
			thisIdent := p.factory.NewIdentifier("this")
			thisIdent.Loc = thisTag.Loc
			thisIdent.Flags = p.contextFlags | ast.NodeFlagsReparsed
			parameter = p.factory.NewParameterDeclaration(nil, nil, thisIdent, nil, nil, nil)
			if thisTag.TypeExpression != nil {
				parameter.AsParameterDeclaration().Type = p.factory.DeepCloneReparse(thisTag.TypeExpression.Type())
			}
		} else {
			jsparam := param.AsJSDocParameterOrPropertyTag()
			parameter = p.factory.NewParameterDeclaration(nil, nil, p.factory.DeepCloneReparse(jsparam.Name()), p.makeQuestionIfOptional(jsparam), nil, nil)
			if jsparam.TypeExpression != nil {
				parameter.AsParameterDeclaration().Type = p.reparseJSDocTypeLiteral(jsparam.TypeExpression.Type())
			}
		}
		p.finishReparsedNode(parameter, param)
		parameters = append(parameters, parameter)
	}
	signature.FunctionLikeData().Parameters = p.newNodeList(jsSignature.AsJSDocSignature().Parameters.Loc, parameters)

	if jsSignature.Type() != nil && jsSignature.Type().AsJSDocReturnTag().TypeExpression != nil {
		signature.FunctionLikeData().Type = p.factory.DeepCloneReparse(jsSignature.Type().AsJSDocReturnTag().TypeExpression.Type())
	}
	loc := tag
	if tag.Kind == ast.KindJSDocOverloadTag {
		loc = tag.AsJSDocOverloadTag().TagName
	}
	p.finishReparsedNode(signature, loc)
	return signature
}

func (p *Project) GetLanguageServiceForRequest(ctx context.Context) (*ls.LanguageService, func()) {
	if core.GetRequestID(ctx) == "" {
		panic("context must already have a request ID")
	}
	program := p.GetProgram()
	if program == nil {
		panic("must have gced by other request")
	}
	checkerPool := p.checkerPool
	snapshot := &snapshot{
		project:          p,
		positionEncoding: p.host.PositionEncoding(),
		program:          program,
	}
	languageService := ls.NewLanguageService(ctx, snapshot)
	cleanup := func() {
		if checkerPool.isRequestCheckerInUse(core.GetRequestID(ctx)) {
			panic(fmt.Errorf("checker for request ID %s not returned to pool at end of request", core.GetRequestID(ctx)))
		}
	}
	return languageService, cleanup
}

func (s *Service) ChangeFile(document lsproto.VersionedTextDocumentIdentifier, changes []lsproto.TextDocumentContentChangeEvent) error {
	fileName := ls.DocumentURIToFileName(document.Uri)
	path := s.toPath(fileName)
	scriptInfo := s.documentStore.GetScriptInfoByPath(path)
	if scriptInfo == nil {
		return fmt.Errorf("file %s not found", fileName)
	}

	textChanges := make([]core.TextChange, len(changes))
	for i, change := range changes {
		if partialChange := change.TextDocumentContentChangePartial; partialChange != nil {
			textChanges[i] = s.converters.FromLSPTextChange(scriptInfo, partialChange)
		} else if wholeChange := change.TextDocumentContentChangeWholeDocument; wholeChange != nil {
			textChanges[i] = core.TextChange{
				TextRange: core.NewTextRange(0, len(scriptInfo.Text())),
				NewText:   wholeChange.Text,
			}
		} else {
			return errors.New("invalid change type")
		}
	}

	s.applyChangesToFile(scriptInfo, textChanges)
	return nil
}

