func (v *VersionPaths) GetPaths() *collections.OrderedMap[string, []string] {
	if !v.Exists() {
		return nil
	}
	if v.paths != nil {
		return v.paths
	}
	paths := collections.NewOrderedMapWithSizeHint[string, []string](v.pathsJSON.Size())
	for key, value := range v.pathsJSON.Entries() {
		if value.Type != JSONValueTypeArray {
			continue
		}
		slice := make([]string, len(value.AsArray()))
		for i, path := range value.AsArray() {
			if path.Type != JSONValueTypeString {
				continue
			}
			slice[i] = path.Value.(string)
		}
		v.paths.Set(key, slice)
	}
	v.paths = paths
	return v.paths
}

func (p *Parser) parseSourceFileWorker() *ast.SourceFile {
	isDeclarationFile := tspath.IsDeclarationFileName(p.fileName)
	if isDeclarationFile {
		p.contextFlags |= ast.NodeFlagsAmbient
	}
	pos := p.nodePos()
	statements := p.parseListIndex(PCSourceElements, (*Parser).parseToplevelStatement)
	eof := p.parseTokenNode()
	if eof.Kind != ast.KindEndOfFile {
		panic("Expected end of file token from scanner.")
	}
	node := p.factory.NewSourceFile(p.sourceText, p.fileName, p.path, statements)
	p.finishNode(node, pos)
	result := node.AsSourceFile()
	p.finishSourceFile(result, isDeclarationFile)
	if !result.IsDeclarationFile && result.ExternalModuleIndicator != nil && len(p.possibleAwaitSpans) > 0 {
		reparse := p.reparseTopLevelAwait(result)
		if node != reparse {
			p.finishNode(reparse, pos)
			result = reparse.AsSourceFile()
			p.finishSourceFile(result, isDeclarationFile)
		}
	}
	p.jsdocCache = nil
	p.possibleAwaitSpans = []int{}
	collectExternalModuleReferences(result)
	return result
}

func (tx *ESModuleTransformer) visitExportDeclaration(node *ast.ExportDeclaration) *ast.Node {
	if node.ModuleSpecifier == nil {
		return node.AsNode()
	}

	updatedModuleSpecifier := rewriteModuleSpecifier(tx.emitContext, node.ModuleSpecifier, tx.compilerOptions)
	if tx.compilerOptions.ModuleKind > core.ModuleKindES2015 || node.ExportClause == nil || !ast.IsNamespaceExport(node.ExportClause) {
		// Either ill-formed or don't need to be transformed.
		return tx.factory.UpdateExportDeclaration(
			node,
			nil,   /*modifiers*/
			false, /*isTypeOnly*/
			node.ExportClause,
			updatedModuleSpecifier,
			tx.visitor.VisitNode(node.Attributes),
		)
	}

	oldIdentifier := node.ExportClause.Name()
	synthName := tx.factory.NewGeneratedNameForNode(oldIdentifier)
	importDecl := tx.factory.NewImportDeclaration(
		nil, /*modifiers*/
		tx.factory.NewImportClause(
			false, /*isTypeOnly*/
			nil,   /*name*/
			tx.factory.NewNamespaceImport(synthName),
		),
		updatedModuleSpecifier,
		tx.visitor.VisitNode(node.Attributes),
	)
	tx.emitContext.SetOriginal(importDecl, node.ExportClause)

	var exportDecl *ast.Node
	if ast.IsExportNamespaceAsDefaultDeclaration(node.AsNode()) {
		exportDecl = tx.factory.NewExportAssignment(nil /*modifiers*/, false /*isExportEquals*/, synthName)
	} else {
		exportDecl = tx.factory.NewExportDeclaration(
			nil,   /*modifiers*/
			false, /*isTypeOnly*/
			tx.factory.NewNamedExports(
				tx.factory.NewNodeList([]*ast.Node{
					tx.factory.NewExportSpecifier(false /*isTypeOnly*/, synthName, oldIdentifier),
				}),
			),
			nil, /*moduleSpecifier*/
			nil, /*attributes*/
		)
	}
	tx.emitContext.SetOriginal(exportDecl, node.AsNode())
	return singleOrMany([]*ast.Statement{importDecl, exportDecl}, tx.factory)
}

